//! Port lockfiles: per-firmware facts (anchors with the sha256 of the bytes they name, allocatable
//! regions, container limits), keyed by the sha256 of the stock `.syx`. Generated by
//! `tools/patchkit/port_resolve.py`; patchkit only reads them and verifies the anchor hashes.

use crate::error::*;
use serde::{Deserialize, Serialize};

#[derive(Clone, Debug, Deserialize, Serialize)]
pub struct Port {
    pub port: PortInfo,
    pub limits: Limits,
    #[serde(default)]
    pub region: Vec<Region>,
    #[serde(default)]
    pub anchor: Vec<Anchor>,
    #[serde(default)]
    pub hook: Vec<Hook>,
}

#[derive(Clone, Debug, Deserialize, Serialize)]
pub struct PortInfo {
    pub device: String,
    pub version: String,
    pub syx_sha256: String,
    pub main_sha256: String,
    /// The DSP section's hash; absent in the port of a device without a DSP.
    #[serde(default)]
    pub dsp_sha256: Option<String>,
    pub resolved_by: String,
}

#[derive(Clone, Debug, Deserialize, Serialize)]
pub struct Limits {
    pub container_max: u64,
    /// 0 on a device without a DSP; a port with a DSP must state both (`Port::parse` refuses a port that leaves one out).
    #[serde(default)]
    pub dsp_stored_max: u64,
    #[serde(default)]
    pub dsp_depacked_max: u64,
    pub main_staged_max: u64,
}

#[derive(Clone, Debug, Deserialize, Serialize)]
pub struct Region {
    pub name: String,
    pub cpu: String,
    pub start: u64,
    pub end: u64,
    #[serde(default)]
    pub excludes: Vec<[u64; 2]>,
    pub mark: String,
}

fn code() -> String {
    "code".into()
}

#[derive(Clone, Debug, Deserialize, Serialize)]
pub struct Anchor {
    pub name: String,
    pub cpu: String,
    /// `code` (bytes at `addr`), `data` (likewise) or `value` (`addr` is a number read from the
    /// `len` bytes at `src`, for example the operand of an instruction).
    #[serde(default = "code")]
    pub kind: String,
    pub addr: u64,
    /// SHARC code: the short-word (pc) address.
    #[serde(default)]
    pub pm: Option<u64>,
    pub len: u64,
    pub sha256: String,
    #[serde(default)]
    pub src: Option<u64>,
    pub mark: String,
    pub rule: String,
}

/// A declared hook point: the site anchor, a byte offset from it and how the displaced code is handled.
#[derive(Clone, Debug, Deserialize, Serialize)]
pub struct Hook {
    pub name: String,
    pub site: String,
    #[serde(default)]
    pub offset: i64,
    /// `before` (displaced instructions still run), `replace` (they are dropped) or `retarget`
    pub mode: String,
    /// `regs.clobbers` of the declaration (ports/fw), as written: registers or ranges like `d0-d1`. A guarded stub's scratch register is one of them.
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub clobbers: Vec<String>,
    /// The site facts of a hook that a service uses (`ports/fw` `users`), written by `port_resolve` from the local firmware (`patchkit port-facts`); a hook of
    /// no service has none. No firmware bytes: a length, a kind and a truncated hash. `len` is the bytes of the displaced whole instructions (at least 6, the jump).
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub len: Option<u32>,
    /// `raw` (the service redoes the instructions), `tail` (`tail = true` of the declaration) or `stock` (`stock = true`): the last two copy the displaced bytes.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub kind: Option<String>,
    /// The first 8 bytes of the sha256 of the displaced bytes, as 16 hex digits.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub check: Option<String>,
    /// Reserved: re-encodings that the displaced bytes need to run elsewhere (a PC-relative operand). Empty today; the port build refuses any.
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub fixups: Vec<Fixup>,
}

/// One fixup of a copied site (reserved).
#[derive(Clone, Debug, PartialEq, Eq, Deserialize, Serialize)]
pub struct Fixup {
    /// Byte offset in the displaced bytes.
    pub at: u32,
    /// The form to re-encode (for example `pcrel16_to_abs32`).
    pub form: String,
}

impl Port {
    pub fn parse(text: &str) -> Result<Port> {
        let p: Port = toml::from_str(text)?;
        if p.port.dsp_sha256.as_deref().is_some_and(|h| !h.is_empty()) {
            // the field defaults to 0, which would make every DSP image "too big": a port with a DSP has to say its limits
            let raw: toml::Value = toml::from_str(text)?;
            for field in ["dsp_stored_max", "dsp_depacked_max"] {
                if raw.get("limits").and_then(|l| l.get(field)).is_none() {
                    return Err(err!(
                        "port {}: [limits] {field} is missing, and the port has a DSP",
                        p.port.version
                    ));
                }
            }
        }
        if p.port.syx_sha256.len() != 64 {
            return Err(err!("port {}: syx_sha256 is not a sha256", p.port.version));
        }
        Ok(p)
    }

    pub fn id(&self) -> String {
        format!("{}-{}", self.port.device, self.port.version)
    }

    pub fn anchor(&self, name: &str) -> Option<&Anchor> {
        self.anchor.iter().find(|a| a.name == name)
    }

    pub fn hook(&self, name: &str) -> Option<&Hook> {
        self.hook.iter().find(|h| h.name == name)
    }

    pub fn region(&self, name: &str) -> Option<&Region> {
        self.region.iter().find(|r| r.name == name)
    }

    /// Free ranges of a region after its excludes, in address order.
    pub fn region_ranges(&self, name: &str) -> Vec<(u64, u64)> {
        let Some(r) = self.region(name) else {
            return vec![];
        };
        let mut ex = r.excludes.clone();
        ex.sort();
        let mut out = vec![];
        let mut at = r.start;
        for [s, e] in ex {
            if s > at {
                out.push((at, s.min(r.end)));
            }
            at = at.max(e);
        }
        if at < r.end {
            out.push((at, r.end));
        }
        out
    }
}

/// All ports known to a build, keyed by stock `.syx` sha256.
#[derive(Clone, Debug, Default)]
pub struct Registry {
    pub ports: Vec<Port>,
}

impl Registry {
    pub fn from_texts<'a>(texts: impl IntoIterator<Item = &'a str>) -> Result<Registry> {
        let mut ports = vec![];
        for t in texts {
            ports.push(Port::parse(t)?);
        }
        Ok(Registry { ports })
    }

    pub fn find(&self, syx_sha256: &str) -> Option<&Port> {
        self.ports.iter().find(|p| p.port.syx_sha256 == syx_sha256)
    }

    pub fn by_id(&self, id: &str) -> Option<&Port> {
        self.ports.iter().find(|p| p.id() == id)
    }
}

#[cfg(not(target_arch = "wasm32"))]
impl Registry {
    pub fn from_dir(dir: &std::path::Path) -> Result<Registry> {
        let mut texts = vec![];
        let rd = std::fs::read_dir(dir).map_err(|e| err!("{}: {e}", dir.display()))?;
        let mut paths: Vec<_> = rd.filter_map(|e| e.ok()).map(|e| e.path()).collect();
        paths.sort();
        for p in paths {
            if p.extension().is_some_and(|e| e == "toml") {
                texts.push(std::fs::read_to_string(&p).map_err(|e| err!("{}: {e}", p.display()))?);
            }
        }
        Registry::from_texts(texts.iter().map(|s| s.as_str()))
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn text(dsp: bool, limits: &str) -> String {
        let h = "a".repeat(64);
        let dsp = if dsp {
            format!("dsp_sha256 = \"{h}\"\n")
        } else {
            String::new()
        };
        format!(
            "[port]\ndevice = \"d\"\nversion = \"1\"\nsyx_sha256 = \"{h}\"\nmain_sha256 = \"{h}\"\n{dsp}resolved_by = \"t\"\n[limits]\ncontainer_max = 1\nmain_staged_max = 1\n{limits}"
        )
    }

    #[test]
    fn a_port_with_a_dsp_must_state_both_dsp_limits() {
        let both = "dsp_stored_max = 5\ndsp_depacked_max = 9\n";
        let p = Port::parse(&text(true, both)).unwrap();
        assert_eq!((p.limits.dsp_stored_max, p.limits.dsp_depacked_max), (5, 9));
        for (what, limits) in [
            ("none", ""),
            ("depacked only", "dsp_depacked_max = 9\n"),
            ("stored only", "dsp_stored_max = 5\n"),
        ] {
            let e = Port::parse(&text(true, limits)).unwrap_err().to_string();
            assert!(e.contains("dsp_") && e.contains("missing"), "{what}: {e}");
        }
        // a port without a DSP has none
        assert_eq!(
            Port::parse(&text(false, "")).unwrap().limits.dsp_stored_max,
            0
        );
    }
}
